proof.raw_tex:
\begin{proof}
First, via standard batch optimization bounds, we have
\begin{align*}
    \|x_{kT}-x_{(k-1)T}\opt\|\leq \frac{2\sqrt{\kappa}}{T}\|x_{(k-1)T}-x_{(k-1)T}\opt\|.
\end{align*}
Thus,
\begin{align*}
    \|x_{kT}-x_{kT}\opt\|&\leq\frac{2\sqrt{\kappa}}{T}\|x_{(k-1)T}-x_{(k-1)T}\opt\|+T\sigma\\
    &\leq \left(\frac{2\sqrt{\kappa}}{T}\right)^k\|x_0-x_0\opt\|+\frac{T\sigma}{1-\frac{2\sqrt{\kappa}}{T}}\\
    &= \left(\frac{2\sqrt{\kappa}}{T}\right)^k\|x_0-x_0\opt\|+\frac{T^2\sigma}{T-2\sqrt{\kappa}}
\end{align*}
and so
\begin{align*}
    \|x_t-x_t\opt\| &= \|x_{T\lfloor t/T \rfloor}-x_t\opt\|\\
    &\leq \|x_{T\lfloor t/T \rfloor}-x_{T\lfloor t/T \rfloor}\opt\|+\|x_t\opt-x_{T\lfloor t/T \rfloor}\opt\|\\
    &\leq \left(\frac{2\sqrt{\kappa}}{T}\right)^{\lfloor t/T \rfloor}\|x_0-x_0\opt\|+\frac{T^2\sigma}{T-2\sqrt{\kappa}}+T\sigma.
\end{align*}
Then, taking the limit supremum, we get
\begin{align*}
    \limsup_{t\to\infty}\|x_t-x_t\opt\| &\leq \frac{T^2\sigma}{T-2\sqrt{\kappa}}+T\sigma\\
    &= \frac{2T\sigma\left(T-\sqrt{\kappa}\right)}{T-2\sqrt{\kappa}}\\
    &= \frac{2c(c-1)}{c-2}\sqrt{\kappa}\sigma.
\end{align*}
\end{proof}

